class FeatureCollinearityAnalyzer:
    """Detects redundant feature pairs before linear modeling or PCA."""

    def __init__(self, corr_threshold: float = 0.90) -> None:
        self.corr_threshold = corr_threshold

    def find_highly_correlated_pairs(
        self, corr: np.ndarray, feature_names: list[str]
    ) -> list[tuple[str, str, float]]:
        d = corr.shape[0]
        flagged: list[tuple[str, str, float]] = []
        for i in range(d):
            for j in range(i + 1, d):
                if abs(corr[i, j]) >= self.corr_threshold:
                    flagged.append((feature_names[i], feature_names[j], float(corr[i, j])))
        return flagged

    def analyze(self, X: np.ndarray, feature_names: list[str]) -> dict:
        cov, corr = covariance_and_correlation(X)
        return {
            "cov": cov,
            "corr": corr,
            "redundant_pairs": self.find_highly_correlated_pairs(corr, feature_names),
        }

import numpy as np


class MinMaxScaler:
    """Reference scaler scaling each feature to [0, 1] using train statistics."""

    def __init__(self) -> None:
        self.min_: np.ndarray | None = None
        self.range_: np.ndarray | None = None

    def fit(self, X: np.ndarray) -> "MinMaxScaler":
        X_arr = np.asarray(X, dtype=np.float64)
        self.min_ = np.min(X_arr, axis=0)
        span = np.max(X_arr, axis=0) - self.min_
        self.range_ = np.where(span == 0.0, 1.0, span)
        return self

    def transform(self, X: np.ndarray) -> np.ndarray:
        if self.min_ is None or self.range_ is None:
            raise RuntimeError("MinMaxScaler must be fitted before calling transform.")
        X_arr = np.asarray(X, dtype=np.float64)
        return (X_arr - self.min_) / self.range_


