class ThresholdEvaluator:
    """Sweeps decision thresholds to choose an optimal F-beta operating point."""

    def __init__(self, beta: float = 1.0) -> None:
        self.beta = beta

    def sweep(
        self, y_true: np.ndarray, y_prob: np.ndarray, thresholds: list[float]
    ) -> list[dict[str, int | float]]:
        return [
            {"threshold": t, **classification_metrics(y_true, y_prob, t, beta=self.beta)}
            for t in thresholds
        ]

    def find_best_threshold(
        self, y_true: np.ndarray, y_prob: np.ndarray, thresholds: list[float]
    ) -> dict[str, int | float]:
        results = self.sweep(y_true, y_prob, thresholds)
        return max(results, key=lambda r: (r["f_beta"], r["recall"]))

