class ProbabilisticLossSuite:
    """Evaluates binary and multi-class probabilistic predictions against baselines."""

    @staticmethod
    def multiclass_log_loss(
        y_true_idx: np.ndarray, probs: np.ndarray, eps: float = 1e-15
    ) -> float:
        y_idx = np.asarray(y_true_idx, dtype=np.int64).ravel()
        p = np.asarray(probs, dtype=np.float64)
        p = np.clip(p, eps, 1.0 - eps)
        p = p / np.sum(p, axis=1, keepdims=True)
        chosen = p[np.arange(y_idx.size), y_idx]
        return float(-np.mean(np.log(chosen)))

    def evaluate_vs_prior_baseline(
        self, y_true: np.ndarray, y_prob: np.ndarray, eps: float = 1e-15
    ) -> dict[str, float]:
        y_t = np.asarray(y_true, dtype=np.float64)
        prior_prob = np.full_like(y_t, fill_value=float(np.mean(y_t)))
        model_loss = binary_log_loss(y_t, y_prob, eps=eps)
        baseline_loss = binary_log_loss(y_t, prior_prob, eps=eps)
        return {
            "model_log_loss": model_loss,
            "prior_baseline_loss": baseline_loss,
            "relative_improvement": (
                (baseline_loss - model_loss) / baseline_loss if baseline_loss > 0 else 0.0
            ),
        }

