def _norm_ppf(p: float) -> float:
    """Acklam's rational approximation for standard normal inverse CDF (< 1e-9 error)."""
    if not (0.0 < p < 1.0):
        raise ValueError("p must lie strictly in (0, 1).")
    a = (
        -3.969683028665376e01, 2.209460984245205e02, -2.759285104469687e02,
        1.383577518672690e02, -3.066479806614716e01, 2.506628277459239e00,
    )
    b = (
        -5.447609879822406e01, 1.615858368580409e02, -1.556989798598866e02,
        6.680131188771972e01, -1.328068155288572e01,
    )
    c = (
        -7.784894002430293e-03, -3.223964580411365e-01, -2.400758277161838e00,
        -2.549732539343734e00, 4.374664141464968e00, 2.938163982698783e00,
    )
    d = (
        7.784695709041462e-03, 3.224671290700398e-01,
        2.445134137142996e00, 3.754408661907416e00,
    )
    p_low, p_high = 0.02425, 1.0 - 0.02425
    if p < p_low:
        q = math.sqrt(-2.0 * math.log(p))
        return (((((c[0]*q + c[1])*q + c[2])*q + c[3])*q + c[4])*q + c[5]) / ((((d[0]*q + d[1])*q + d[2])*q + d[3])*q + 1.0)
    if p <= p_high:
        q = p - 0.5
        r = q * q
        return (((((a[0]*r + a[1])*r + a[2])*r + a[3])*r + a[4])*r + a[5]) * q / (((((b[0]*r + b[1])*r + b[2])*r + b[3])*r + b[4])*r + 1.0)
    q = math.sqrt(-2.0 * math.log(1.0 - p))
    return -(((((c[0]*q + c[1])*q + c[2])*q + c[3])*q + c[4])*q + c[5]) / ((((d[0]*q + d[1])*q + d[2])*q + d[3])*q + 1.0)


class ABExperimentPlatform:
    """Designs sample size power requirements and evaluates two-proportion A/B tests."""

    @staticmethod
    def required_sample_size_per_variant(
        baseline_rate: float, mde: float, alpha: float = 0.05, power: float = 0.80
    ) -> int:
        p1 = baseline_rate
        p2 = baseline_rate + mde
        if not (0.0 < p1 < 1.0 and 0.0 < p2 < 1.0 and mde != 0.0):
            raise ValueError("Invalid baseline_rate or mde.")
        z_alpha = _norm_ppf(1.0 - alpha / 2.0)
        z_beta = _norm_ppf(power)
        p_bar = 0.5 * (p1 + p2)
        num = (z_alpha * math.sqrt(2.0 * p_bar * (1.0 - p_bar)) + z_beta * math.sqrt(p1 * (1.0 - p1) + p2 * (1.0 - p2))) ** 2
        return int(math.ceil(num / (mde ** 2)))

    def evaluate(
        self, c_conv: int, c_n: int, t_conv: int, t_n: int, alpha: float = 0.05
    ) -> dict[str, float | bool]:
        res = ab_test_z_stat_and_pvalue(c_conv, c_n, t_conv, t_n)
        return {**res, "statistically_significant": res["p_value"] < alpha}
